import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { defineConfig } from 'vite';
import preact from '@preact/preset-vite';

// Every page address to prerender (album, instrument, song…), generated by `npm run data`.
const routes: string[] = existsSync('data/routes.json') ? JSON.parse(readFileSync('data/routes.json', 'utf8')) : [];

// Content (tabs_*, lyrics, data, images…) stays at the repo root. The dev server
// serves it as-is; `npm run build` copies it into dist/ (tools/copy-content.mjs).
export default defineConfig({
  base: '/', // site lives at the root of fftabs.com
  publicDir: false,
  plugins: [
    preact({
      prerender: {
        enabled: true,
        renderTarget: '#root',
        prerenderScript: fileURLToPath(new URL('./src/prerender.tsx', import.meta.url)),
        additionalPrerenderRoutes: routes,
        previewMiddlewareEnabled: true,
      },
    }),
  ],
  // fixed ports so .vscode/launch.json always opens the right address
  server: { port: 5173, strictPort: true },
  preview: { port: 4173, strictPort: true },
  build: {
    outDir: 'dist',
    assetsDir: 'assets',
    emptyOutDir: true,
  },
});
